use super::{authority::{AuthoritySet,Capability},decision::Decision,evidence::{Evidence,exact_subject},exclusion::ExclusionReason,falsifier::{Falsifier,Falsification},subject::SubjectId};
pub struct AdmissionRequest<'a>{pub subject:&'a SubjectId,pub principal:&'a str,pub scope:&'a str,pub claim:&'a str,pub authority:&'a AuthoritySet,pub evidence:&'a[Evidence],pub falsifiers:&'a[Falsifier]}
pub fn evaluate(r:AdmissionRequest<'_>)->Decision{let mut x=vec![];if r.subject.validate().is_err(){x.push(ExclusionReason::WrongSubject)}if !r.authority.allows(r.principal,&Capability::Construct,r.scope){x.push(ExclusionReason::MissingAuthority)}let ev=exact_subject(r.subject,r.evidence);if ev.is_empty(){x.push(ExclusionReason::InsufficientEvidence)}if r.falsifiers.iter().any(|f|matches!(f.evaluate(r.claim,r.evidence),Falsification::Refuted{..})){x.push(ExclusionReason::FailedFalsifier)}if x.is_empty(){Decision::Admit{claim:r.claim.into(),evidence:ev.into_iter().map(|e|e.id.clone()).collect()}}else{Decision::Refuse{claim:r.claim.into(),reasons:x}}}